type Post = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
};

type RouteContext = {
  params: Promise<{ id: string }>;
};

export async function GET(
  _request: Request,
  { params }: RouteContext
) {
  const { id } = await params;
  const post: Post = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(
  request: Request,
  { params }: RouteContext
) {
